import sys; sys.path.insert(0,'/tmp/ss-build/tools/c10')
from lib10 import *
S='social-science'
def B(ch,cn,t,tn,*a,**k): build(S,ch,t,tn,*a,cname=cn,tname=tn,**k)
# ---- Geography 1
C,CN='geo-resources-and-development','Geography 1: Resources and Development'
B(C,CN,'resources-and-development','Resources and Development',
 "Is the soil a gift or an asset?",
 "A farmer in Punjab and a miner in Jharkhand both depend on the earth. But a handful of soil is useful only when people know how to use it. That is the big idea of this chapter: nature gives materials, human beings turn them into resources.",
 [("The textbook says that everything in our environment that can satisfy our needs is a resource, provided it is technologically accessible, economically feasible and culturally acceptable.","resource"),
  ("Resources are not just free gifts of nature. Human beings transform materials into resources through technology and create institutions to speed up development.","nature + technology + institutions"),
  ("Resources are classified in four ways: by origin as biotic and abiotic, by exhaustibility as renewable and non-renewable, by ownership as individual, community, national and international, and by status of development as potential, developed, stock and reserves.","4 ways to classify"),
  ("Careless use of resources causes depletion, divides society into haves and have-nots, and leads to global warming, ozone depletion and land degradation. So we need sustainable development, meaning development that does not compromise the needs of future generations.","sustainable development"),
  ("The Rio de Janeiro Earth Summit of 1992 adopted Agenda 21, which asks every local government to draw up its own local Agenda 21.","Rio 1992, Agenda 21"),
  ("Resource planning is a three-step process: identify and inventory resources, evolve a planning structure with technology and institutions, and match the plan with national development plans.","resource planning"),
  ("Land is used for forests, land not available for cultivation, other uncultivated land, fallow land and net sown area. Soils in India are alluvial, black, red and yellow, laterite, arid and forest soils.","land use and soils"),
  ("Land degradation is checked by afforestation, proper grazing, shelter belts, stabilising sand dunes with thorny bushes and controlling mining and industrial waste.","soil conservation")],
 ("A state has 40 per cent of its area as net sown area and 20 per cent as forest. What per cent is left for all other uses?",[("Add the two given shares: 40 + 20 = 60 per cent.","Total area is 100 per cent."),("Subtract from the whole: 100 - 60 = 40 per cent.","The rest is fallow, uncultivated and non-agricultural use.")]),
 ("Explain why a resource is more than a free gift of nature.",["Resource needs technology, economy and culture to be usable","Humans transform materials into resources","Sustainable use keeps resources for the future"],["Thinking all materials in nature are resources by themselves"]),
 ["Resources depend on technology, economic feasibility and cultural acceptance.","They are classified by origin, exhaustibility, ownership and status of development.","Sustainable development protects the needs of future generations.","India has six main soil types and five main land-use categories."],
 [mcq("g1-1",1,"Which of these is a biotic resource?","Fisheries",[("Iron ore","Minerals are abiotic."),("Water","Water is an abiotic resource.")],"Biotic resources come from living things such as forests, animals and fisheries."),
  tf("g1-2",1,"Sustainable development means growth without harming the needs of future generations.",True,"This is the textbook definition."),
  mcq("g1-3",2,"The first International Earth Summit in Rio de Janeiro was held in","1992",[("1974","1974 is when Gandhian philosophy of resource use was discussed, not the Rio Summit."),("2002","2002 was the Johannesburg summit.")],"Agenda 21 came from Rio, 1992."),
  mcq("g1-4",2,"Assertion (A): Resources are a function of human activities. Reason (R): Human beings transform materials into resources.","Both A and R are true and R explains A",[("A is true but R is false","R is stated in the text."),("A is false but R is true","A is the chapter's main idea.")],"Humans are essential components of resources."),
  short("g1-5",2,"Name the soil type most widespread in the northern plains.",["alluvial","alluvial soil"],"Alluvial soil is deposited by the Indus, Ganga and Brahmaputra rivers.",[("black","Black soil is typical of the Deccan lava region.")]),
  num("g1-6",2,"How many ways of classifying resources does the chapter give?",4,"Origin, exhaustibility, ownership and status of development.",[(3,"There are four bases of classification.")]),
  mcq("g1-7",3,"Which method helps check soil erosion on hill slopes?","Contour ploughing",[("Overgrazing","Overgrazing causes erosion."),("Deforestation","Deforestation increases erosion.")],"Ploughing along contour lines slows water flow."),
  tf("g1-8",3,"Net sown area is land sown more than once.",False,"Net sown area is the area sown at least once; area sown more than once is gross cropped area.")])
# ---- Geography 2
C,CN='geo-forest-and-wildlife','Geography 2: Forest and Wildlife Resources'
B(C,CN,'forest-and-wildlife-resources','Forest and Wildlife Resources',
 "Why did the tiger numbers fall?",
 "In the early 1900s, India had tens of thousands of tigers. By 1973 the number had fallen so low that the government launched Project Tiger. Today we learn why wildlife disappears and how people save it.",
 [("India is rich in biodiversity, which means the variety of plants, animals and micro-organisms found in a region. Flora means plants and fauna means animals of a region.","biodiversity"),
  ("Many species are in danger. The IUCN groups them as normal, endangered, vulnerable, rare, endemic and extinct species.","IUCN categories"),
  ("Reasons for depletion include expansion of agriculture, large development projects, mining, grazing, fuelwood collection and, as the book stresses, unequal access to resources.","causes"),
  ("The Indian Wildlife Protection Act of 1972 created protected areas and banned hunting. Project Tiger, launched in 1973, set up tiger reserves such as Corbett and Sunderbans.","1972 Act, 1973 Project Tiger"),
  ("Forests are classified as reserved, protected and unclassed. Reserved forests are the most valuable for conservation and form more than half of the total forest land.","reserved, protected, unclassed"),
  ("Communities help conservation. The Chipko movement in the Himalayas saved trees, and villagers in Sariska and Alwar guard their forests.","Chipko"),
  ("Joint Forest Management involves local communities in protecting degraded forests, and in return they share the benefits.","JFM"),
  ("Sacred groves and traditional practices of worship protect species. Conservation is a shared duty of government and people.","sacred groves")],
 ("A reserve had 2,000 tigers spread over 4 states equally. How many are in each state?",[("Divide the total by the number of states.","Equal sharing."),("2000 / 4 = 500 tigers in each state.","Check: 4 x 500 = 2000.")]),
 ("Explain how people and government together protect forests.",["Government laws and projects","Community movements like Chipko","Joint Forest Management shares benefits"],["Believing only the government can protect forests"]),
 ["Biodiversity is the variety of life; flora and fauna are plants and animals.","The 1972 Act and Project Tiger protect wildlife.","Forests are reserved, protected or unclassed.","Community effort such as Chipko and JFM is vital."],
 [mcq("g2-1",1,"Project Tiger was launched in","1973",[("1947","1947 is Independence."),("1992","1992 is the Rio Summit.")],"It protects the tiger and its habitat."),
  tf("g2-2",1,"Flora means the animals of a region.",False,"Flora means plants; fauna means animals."),
  mcq("g2-3",2,"Which forests are considered most valuable for conservation?","Reserved forests",[("Unclassed forests","They are other forests and wastelands."),("Protected forests","They are protected from further depletion but are less valuable than reserved.")],"Reserved forests get the highest protection."),
  short("g2-4",2,"Name the movement of hugging trees in the Himalayas.",["chipko","chipko movement"],"Villagers hugged trees to stop felling.",[("appiko","Appiko is a southern-India movement, not the Himalayan one.")]),
  mcq("g2-5",2,"Assertion (A): Community participation is essential for forest conservation. Reason (R): Communities live close to forests and depend on them.","Both A and R are true and R explains A",[("A is true but R is false","R is true."),("Both are false","Both statements are correct.")],"People who depend on forests protect them best when given a role."),
  tf("g2-6",2,"Joint Forest Management started in Odisha in 1988.",True,"Odisha passed the first resolution for JFM in 1988."),
  mcq("g2-7",3,"A species whose numbers are so low that it may soon disappear is called","endangered",[("normal","Normal species are in usual numbers."),("extinct","Extinct species no longer exist.")],"Endangered species are at risk of extinction."),
  short("g2-8",3,"Which law of 1972 protects wildlife?",["wildlife protection act","indian wildlife protection act"],"It banned hunting and created sanctuaries.",[("forest act","The Indian Forest Act is of 1927.")])])
# ---- Geography 3
C,CN='geo-water-resources','Geography 3: Water Resources'
B(C,CN,'water-resources','Water Resources',
 "Three-fourths water, yet thirsty",
 "Our earth is three-fourths water, but only a tiny part is fresh water we can use. In many places women walk miles for a pot of water. How do we save it?",
 [("Three-fourths of the earth's surface is covered with water, but only a small share is fresh water that can be used. It comes from surface run-off and groundwater, renewed by the hydrological cycle.","fresh water is scarce"),
  ("Water scarcity is caused by growing population, unequal access, and over-use for irrigation, industry and cities. It is also made worse by pollution.","scarcity"),
  ("Irrigated agriculture is the largest consumer, and over-extraction of groundwater lowers the water table.","groundwater"),
  ("Multipurpose river projects, such as the Bhakra-Nangal, Hirakud and Sardar Sarovar dams, serve irrigation, power, flood control and fish breeding.","multipurpose projects"),
  ("Dams have drawbacks: they affect natural flow, displace people and reduce fertility downstream. This led to movements such as the Narmada Bachao Andolan.","drawbacks"),
  ("Rainwater harvesting is an old answer. Examples are rooftop harvesting in Rajasthan, the guls and kuls in the Himalayas and the bamboo drip system in Meghalaya.","rainwater harvesting"),
  ("In Tamil Nadu, rooftop rainwater harvesting structures were made compulsory to all the houses across the state.","Tamil Nadu"),
  ("Tanka in Bikaner, Phalodi and Barmer is an underground tank that stores rain from the roof for drinking.","tanka")],
 ("A rooftop of 100 square metres gets 0.5 m of rain. How many cubic metres of water can be collected, ignoring losses?",[("Volume = area x depth.","Rain depth is a height."),("100 x 0.5 = 50 cubic metres.","50 cubic metres = 50,000 litres.")]),
 ("Describe two ways of saving water in your area.",["Rooftop rainwater harvesting","Prevent wastage and recycle"],["Thinking dams alone solve scarcity"]),
 ["Usable fresh water is a small share of the earth's water.","Over-use and pollution cause scarcity.","Multipurpose projects have benefits and problems.","Rainwater harvesting is a sustainable solution."],
 [mcq("g3-1",1,"Which state made rooftop rainwater harvesting compulsory in all houses?","Tamil Nadu",[("Punjab","Not mentioned for this rule."),("Bihar","Not mentioned for this rule.")],"The chapter names Tamil Nadu."),
  tf("g3-2",1,"Most of the water on earth can be used directly by people.",False,"Only a small proportion is usable fresh water."),
  mcq("g3-3",2,"Bamboo drip irrigation is practised in","Meghalaya",[("Rajasthan","Rajasthan uses tankas."),("Kerala","Not the example given.")],"It is a roughly 200-year-old system."),
  short("g3-4",2,"Name a Himalayan channel system for diverting water.",["kul","guls","kuls","gul"],"Guls and kuls divert stream water to fields in the hills.",[("tanka","A tanka is an underground tank in Rajasthan.")]),
  mcq("g3-5",2,"Assertion (A): Multipurpose projects are not free from problems. Reason (R): They displace people and alter river flow.","Both A and R are true and R explains A",[("A is true but R is false","R is true."),("A is false but R is true","A is the correct conclusion.")],"Benefits come with social and ecological costs."),
  mcq("g3-6",3,"Hirakud dam is on the river","Mahanadi",[("Ganga","Not Hirakud."),("Krishna","Not Hirakud.")],"Hirakud is in Odisha on the Mahanadi."),
  tf("g3-7",3,"Groundwater over-use lowers the water table.",True,"Pumping faster than recharge causes a fall."),
  short("g3-8",3,"What does a tanka store?",["rainwater","water"],"It stores rainwater collected from roofs.",[("grain","It is a water tank.")])])
# ---- Geography 4
C,CN='geo-agriculture','Geography 4: Agriculture'
B(C,CN,'agriculture','Agriculture',
 "What is on your plate?",
 "Every bite of rice, wheat or fruit began in a field. Agriculture employs about two-thirds of Indians. Today we study how and what India grows.",
 [("Types of farming include primitive subsistence, intensive subsistence, and commercial farming, with plantation as a type of commercial farming.","types of farming"),
  ("Primitive subsistence farming uses a hoe, dao and digging stick. In the north-east it is known as jhumming, or slash and burn.","jhumming"),
  ("In intensive subsistence farming, high pressure of population leads to using more labour on small land. Commercial farming uses higher doses of fertilisers and pesticides.","intensive and commercial"),
  ("India has three cropping seasons. Rabi is sown in winter and harvested in summer, kharif is sown with the monsoon, and zaid is a short season between rabi and kharif.","rabi, kharif, zaid"),
  ("Rice is a kharif crop needing high temperature and rainfall. Wheat is a rabi crop of cool growing season, grown in the Ganga-Sutlej plains.","rice and wheat"),
  ("Millets such as jowar, bajra and ragi are coarse grains. Pulses, sugarcane, oilseeds, tea, coffee, rubber and fibre crops such as cotton and jute are other important crops.","other crops"),
  ("Technological reforms like the Green Revolution and White Revolution and institutional reforms such as land consolidation helped farming.","reforms"),
  ("The Bhoodan-Gramdan movement of Vinoba Bhave asked landlords to donate land to the landless. The government now supports farmers with minimum support price and crop insurance.","Bhoodan-Gramdan")],
 ("A farmer grows rice on 3 hectares giving 4 tonnes per hectare. What is the total output?",[("Output = area x yield.","Yield is per hectare."),("3 x 4 = 12 tonnes.","The unit is tonnes.")]),
 ("Explain the difference between rabi and kharif crops.",["Rabi is sown in winter","Kharif is sown with the monsoon","Examples of each"],["Thinking all crops are grown in the same season"]),
 ["Farming types are primitive subsistence, intensive subsistence and commercial.","Rabi, kharif and zaid are the cropping seasons.","Rice, wheat, millets, pulses and cash crops are major crops.","Reforms improved production and fairness."],
 [mcq("g4-1",1,"Wheat is a","rabi crop",[("kharif crop","Rice is the main kharif crop."),("zaid crop","Zaid crops are watermelon, cucumber and similar.")],"Wheat is sown in winter."),
  tf("g4-2",1,"Jhumming is another name for slash and burn farming.",True,"It is practised in the north-east."),
  mcq("g4-3",2,"The Green Revolution mainly increased production of","wheat and rice",[("tea and coffee","Those are plantation crops."),("cotton and jute","Not the main focus.")],"High-yielding varieties spread in Punjab, Haryana and parts of UP."),
  short("g4-4",2,"Which crop is a staple food of eastern and southern India?",["rice"],"Rice needs hot, humid conditions.",[("wheat","Wheat is the staple of the north-west.")]),
  mcq("g4-5",2,"Assertion (A): Tea needs heavy labour. Reason (R): Leaves are plucked by hand and processed quickly.","Both A and R are true and R explains A",[("A is true but R is false","R is true."),("Both false","Both are correct.")],"Tea is a labour-intensive plantation crop."),
  short("g4-6",3,"Who started the Bhoodan-Gramdan movement?",["vinoba bhave"],"Vinoba Bhave asked landlords to donate land.",[("gandhi","Gandhi inspired it but Vinoba started it.")]),
  tf("g4-7",3,"Pulses are mostly grown in rotation with other crops because they restore soil nitrogen.",True,"Pulses are leguminous crops."),
  num("g4-8",3,"Number of cropping seasons in India named in the chapter",3,"Rabi, kharif and zaid.",[(2,"There is also zaid.")])])
# ---- Geography 5
C,CN='geo-minerals-and-energy','Geography 5: Minerals and Energy Resources'
B(C,CN,'minerals-and-energy-resources','Minerals and Energy Resources',
 "What is inside a toothpaste and a train?",
 "A bright smile from toothpaste, the rail track under a train and the electricity in your house all depend on minerals. Today we find where India gets them.",
 [("A mineral is a homogenous naturally occurring substance with a definable internal structure. Minerals are found in ores.","mineral and ore"),
  ("Minerals occur in igneous and metamorphic rocks as veins and lodes, in sedimentary rocks in layers, as alluvial deposits called placers, and in ocean waters.","mode of occurrence"),
  ("Minerals are classified as ferrous (iron, manganese), non-ferrous (copper, bauxite, lead, zinc, tin) and non-metallic (mica, limestone).","classification"),
  ("Iron ore is the backbone of industry. The main belts are Odisha-Jharkhand, Durg-Bastar-Chandrapur, Ballari-Chitradurga-Chikkamagaluru-Tumakuru and Maharashtra-Goa.","iron ore belts"),
  ("Energy resources are conventional such as coal, petroleum, natural gas and electricity, and non-conventional such as solar, wind, tidal and biogas.","conventional and non-conventional"),
  ("Coal is the most abundant fossil fuel in India. Petroleum comes mainly from Mumbai High and Assam, and natural gas from the Krishna-Godavari basin.","coal, petroleum, gas"),
  ("Hydroelectricity and thermal power are the main sources of electricity. Tamil Nadu is a leader in wind energy near Nagercoil and Madurai (additional, not in the textbook).","power"),
  ("We must conserve minerals and energy because they are finite resources, by using them carefully, recycling and using renewable sources.","conservation")],
 ("A power plant burns 5,000 tonnes of coal per day. How much in 30 days?",[("Multiply per-day use by days.","Same rate each day."),("5,000 x 30 = 150,000 tonnes.","Large numbers show why saving matters.")]),
 ("Why should we conserve minerals?",["They are finite and take millions of years to form","Use carefully, recycle and use renewables"],["Thinking minerals renew quickly"]),
 ["Minerals occur in ores in rocks and alluvial deposits.","They are ferrous, non-ferrous or non-metallic.","Energy is conventional or non-conventional.","Conservation is a must."],
 [mcq("g5-1",1,"Which is a ferrous mineral?","Manganese",[("Copper","Copper is non-ferrous."),("Mica","Mica is non-metallic.")],"Iron and manganese are ferrous."),
  tf("g5-2",1,"Coal is a conventional source of energy.",True,"Coal, petroleum, gas and electricity are conventional."),
  mcq("g5-3",2,"Mumbai High is an important source of","petroleum",[("coal","Coal is in the Gondwana fields."),("iron ore","Not related.")],"It is offshore of Mumbai."),
  mcq("g5-4",2,"Assertion (A): Minerals should be conserved. Reason (R): Minerals are a finite resource.","Both A and R are true and R explains A",[("A is true but R is false","R is true."),("A is false but R is true","A is the right conclusion.")],"We cannot make more minerals quickly."),
  short("g5-5",2,"Name the rock in which minerals occur as layers.",["sedimentary","sedimentary rocks"],"Coal and limestone are in sedimentary layers.",[("igneous","Igneous rocks hold veins and lodes.")]),
  mcq("g5-6",3,"Which is a non-conventional source?","Wind energy",[("Natural gas","Conventional."),("Coal","Conventional.")],"Wind, solar, tidal and biogas are non-conventional."),
  tf("g5-7",3,"Placer deposits are found in alluvial sands.",True,"Gold, tin and platinum occur as placers."),
  short("g5-8",3,"Natural gas in the east coast is mostly from which basin?",["krishna-godavari","krishna godavari"],"The KG basin is a major gas field.",[("mumbai high","Mumbai High is mostly oil.")])])
# ---- Geography 6
C,CN='geo-manufacturing-industries','Geography 6: Manufacturing Industries'
B(C,CN,'manufacturing-industries','Manufacturing Industries',
 "From cotton boll to your shirt",
 "Your shirt started as cotton in a field, became yarn in a spinning mill and cloth in a weaving unit. Manufacturing turns raw material into goods of higher value.",
 [("Manufacturing is the production of goods in large quantities after processing raw material into more valuable products. It is called the backbone of development.","manufacturing"),
  ("Industries help agriculture, create jobs and bring in foreign exchange through exports, and reduce poverty and unemployment.","importance"),
  ("Industries are classified by raw material into agro-based and mineral-based, by role into basic and consumer, by capital into small and large, and by ownership into public, private, joint and co-operative.","classification"),
  ("Cotton textiles is a major agro-based industry. Spinning is centred in the cotton belt and weaving is decentralised. India is a leading producer of yarn.","cotton textiles"),
  ("Jute, sugar and silk are other agro-based industries. Sugar mills are shifting to the south and west because cane there has a higher sucrose content.","jute and sugar"),
  ("The iron and steel industry is the basic industry. It needs iron ore, coking coal and limestone, and Bhilai in Chhattisgarh is a public sector steel plant. Jamshedpur, Durgapur, Rourkela and Salem are other well-known centres (additional, not in the textbook).","iron and steel"),
  ("Other industries include aluminium smelting, chemicals, fertiliser, cement, automobile and information technology.","other industries"),
  ("Industries cause air, water, land and noise pollution. Pollution can be reduced by treating waste and using cleaner technologies.","pollution")],
 ("A mill makes 200 shirts a day and each earns Rs 50 profit. What is the profit in 10 days?",[("Daily profit = 200 x 50 = Rs 10,000.","Multiply count and profit."),("For 10 days = Rs 1,00,000.","Value is added by manufacturing.")]),
 ("Why is manufacturing the backbone of development?",["Adds value to raw materials","Creates jobs","Earns foreign exchange"],["Thinking farming has no link to industry"]),
 ["Manufacturing adds value and creates jobs.","Industries can be grouped by raw material, role, capital and ownership.","Steel needs iron ore, coking coal and limestone.","Pollution control matters."],
 [mcq("g6-1",1,"Cotton textiles is a","agro-based industry",[("mineral-based industry","Raw material is cotton, an agricultural product."),("basic industry","Basic industries supply raw material to others, like steel.")],"Raw material comes from farms."),
  tf("g6-2",1,"Bhilai steel plant is in the public sector.",True,"Bhilai in Chhattisgarh is a public sector steel plant."),
  mcq("g6-3",2,"Which is a basic industry?","Iron and steel",[("Biscuits","A consumer industry."),("Sugar","An agro-based consumer industry.")],"Steel supplies other industries."),
  mcq("g6-4",2,"Assertion (A): Industry and agriculture are linked. Reason (R): Agro-industries use farm raw material and industry supplies fertilisers.","Both A and R are true and R explains A",[("A is true but R is false","R is true."),("Both false","Both correct.")],"They depend on each other."),
  short("g6-5",2,"Name a pollution caused by industrial noise.",["noise pollution"],"Machines and generators cause noise.",[("air pollution","That comes from smoke and gases.")]),
  mcq("g6-6",3,"Which is needed for making steel?","Coking coal",[("Cotton","Raw material for textiles."),("Sugarcane","Raw material for sugar.")],"Coking coal, iron ore and limestone."),
  tf("g6-7",3,"Public sector industries are owned by the government.",True,"Ownership classification."),
  short("g6-8",3,"Name an IT hub in south India.",["bengaluru","bangalore","chennai","hyderabad"],"These cities are IT centres.",[("kolkata","Better known for jute.")])])
# ---- Geography 7
C,CN='geo-lifelines-of-national-economy','Geography 7: Lifelines of National Economy'
B(C,CN,'lifelines-of-national-economy','Lifelines of National Economy',
 "How does a parcel travel?",
 "Order a parcel from Delhi to Chennai and it may travel by road, rail, air or even sea. Transport and communication tie the nation together.",
 [("Goods and services move by land, water and air. Transport, communication and trade are the lifelines of the national economy.","transport and trade"),
  ("Roadways are cheaper for short distances and reach even remote villages. India has one of the largest road networks in the world.","roadways"),
  ("Roads are classified as Golden Quadrilateral Super Expressways, National Highways, State Highways, District roads and Other roads, including border roads.","road classes"),
  ("Railways are the principal mode of transport for goods and passengers. Indian Railways is the largest public sector undertaking.","railways"),
  ("Pipelines carry crude oil, natural gas and even water. Waterways are the cheapest means for heavy goods, and National Waterway 1 runs on the Ganga from Prayagraj to Haldia.","pipelines and waterways"),
  ("Major ports include Kandla, Mumbai, Chennai, Visakhapatnam, Kolkata and Kochi. Air transport is the fastest but costliest.","ports and airways"),
  ("Communication includes post, telegram, radio, television, and the internet. Mass media and telecom connect distant places.","communication"),
  ("International trade is the exchange of goods among countries. A country must balance exports and imports, and tourism is also a trade.","trade and tourism")],
 ("A truck carries 10 tonnes at Rs 5 per tonne per km. What is the cost for 400 km?",[("Cost per km = 10 x 5 = Rs 50.","Quantity times rate."),("For 400 km = 50 x 400 = Rs 20,000.","Longer distances cost more.")]),
 ("Why are transport and communication called lifelines?",["They link places and people","They carry goods and information","They support trade"],["Thinking only roads matter"]),
 ["Roadways, railways, pipelines, waterways and airways are the modes.","Chennai, Mumbai and Kandla are among major ports.","Communication includes mass media and internet.","International trade and tourism add to the economy."],
 [mcq("g7-1",1,"The cheapest mode for heavy goods is","waterways",[("airways","Airways are the costliest."),("roadways","Roads are for short distances.")],"Waterways suit bulk cargo."),
  tf("g7-2",1,"National Waterway 1 is on the Ganga.",True,"Prayagraj to Haldia."),
  mcq("g7-3",2,"The fastest mode of transport is","air",[("rail","Slower than air."),("pipeline","Only for fluids.")],"Air saves time but is costly."),
  mcq("g7-4",2,"Assertion (A): Roads are important for remote areas. Reason (R): Roads can reach areas that rail cannot.","Both A and R are true and R explains A",[("A true, R false","R is true."),("Both false","Both are correct.")],"Roads give door-to-door service."),
  short("g7-5",2,"Which port is on the eastern coast of Tamil Nadu?",["chennai"],"Chennai is an old artificial port.",[("kandla","Kandla is in Gujarat.")]),
  mcq("g7-6",3,"Crude oil from wells to refineries often travels through","pipelines",[("airways","Not suited."),("waterways","Sometimes, but pipelines are common inland.")],"Pipelines carry liquids and gases."),
  tf("g7-7",3,"Tourism is a type of trade.",True,"The chapter calls tourism a trade."),
  short("g7-8",3,"Name the highway network connecting Delhi, Mumbai, Chennai and Kolkata.",["golden quadrilateral"],"It forms a quadrilateral across India.",[("grand trunk","An old road, not this network.")])])
print('geo ok')
